#include "kernel.h"

#include <cuco/hash_functions.cuh>
#include <cuco/probing_scheme.cuh>
#include <cuco/static_set.cuh>

#include <cuda/stream_ref>

#include <cstdint>
#include <limits>

void static_set_build_and_probe(
    const std::int32_t* build_keys,
    std::size_t build_size,
    const std::int32_t* probe_keys,
    std::size_t probe_size,
    bool* present,
    cudaStream_t stream) {
  using key_type = std::int32_t;
  constexpr auto empty_key_sentinel = std::numeric_limits<key_type>::min();

  auto stream_ref = cuda::stream_ref{stream};

  auto set = cuco::static_set{
      build_size * 2,
      cuco::empty_key<key_type>{empty_key_sentinel},
      {},
      cuco::linear_probing<1, cuco::default_hash_function<key_type>>{},
      {},
      {},
      {},
      stream_ref};

  set.insert_async(build_keys, build_keys + build_size, stream_ref);
  set.contains_async(probe_keys, probe_keys + probe_size, present, stream_ref);
}

#pragma once

#include <cstddef>
#include <cstdint>
#include <cuda_runtime_api.h>

void static_set_build_and_probe(
    const std::int32_t* build_keys,
    std::size_t build_size,
    const std::int32_t* probe_keys,
    std::size_t probe_size,
    bool* present,
    cudaStream_t stream);

#include "kernel.h"

#include <ATen/cuda/CUDAContext.h>
#include <torch/extension.h>

#include <cstddef>
#include <cstdint>
#include <string>

namespace {

void check_i32_vector(const torch::Tensor& tensor, const char* name) {
  TORCH_CHECK(tensor.is_cuda(), name, " must be a CUDA tensor");
  TORCH_CHECK(tensor.scalar_type() == torch::kInt32, name, " must have int32 dtype");
  TORCH_CHECK(tensor.dim() == 1, name, " must be one-dimensional");
  TORCH_CHECK(tensor.is_contiguous(), name, " must be contiguous");
}

}  // namespace

void run(
    const torch::Tensor& build_keys,
    const torch::Tensor& probe_keys,
    torch::Tensor present) {
  check_i32_vector(build_keys, "build_keys");
  check_i32_vector(probe_keys, "probe_keys");
  TORCH_CHECK(build_keys.numel() > 0, "build_keys must not be empty");
  TORCH_CHECK(present.is_cuda(), "present must be a CUDA tensor");
  TORCH_CHECK(present.scalar_type() == torch::kBool, "present must have bool dtype");
  TORCH_CHECK(present.dim() == 1, "present must be one-dimensional");
  TORCH_CHECK(present.numel() == probe_keys.numel(), "present has the wrong length");
  TORCH_CHECK(present.is_contiguous(), "present must be contiguous");
  TORCH_CHECK(
      build_keys.get_device() == probe_keys.get_device() &&
          build_keys.get_device() == present.get_device(),
      "all tensors must be on the same CUDA device");

  static_set_build_and_probe(
      build_keys.data_ptr<std::int32_t>(),
      static_cast<std::size_t>(build_keys.numel()),
      probe_keys.data_ptr<std::int32_t>(),
      static_cast<std::size_t>(probe_keys.numel()),
      present.data_ptr<bool>(),
      at::cuda::getCurrentCUDAStream(build_keys.get_device()));
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, module) {
  module.def("run", &run, "Build a cuco::static_set and probe membership");
}
